output_schema:
{"formato":"texto","estrutura":"{
  "mode": "create | refine",
  "platform": "mobile | web",
  "project_name": "string",
  "stitch_prompts": [
    {
      "prompt_key": "prompt_1",
      "prompt_type": "high_level | screen_spec | iteration",
      "focus": "string (ex.: 'Home', 'Login', 'Product detail', 'Theme update')",
      "prompt": "string (texto pronto para colar no Stitch)"
    }
  ],
  "prompting_checklist": {
    "clear_target_screen_or_component": true,
    "one_major_change_if_refine": true,
    "vibe_defined": true,
    "theme_consistency_noted": true,
    "imagery_guidance_present": true,
    "language_specified_if_needed": false
  },
  "metadata": {
    "template_version": "1.0",
    "generated_at": "YYYY-MM-DD"
  }
}"}

{"formato":"json","estrutura":"{
  "ad_type": "string",           // valor do menu TIPOS DE PEÇAS (ex.: "social_media/post_estatico")
  "ad_type_label": "string",     // rótulo legível (ex.: "Post Estático")
  "scene_type": "string",        // valor do menu TIPOS DE CENA (ex.: "celular_mesa_cafe")
  "scene_type_label": "string",  // rótulo legível da cena (ex.: "Celular sobre mesa de café")
  "user_scene_description": "string", // descrição livre do usuário
  "scenes": [
    {
      "id": "scene_1",
      "camera_angle": "wide",
      "shot_label": "Visão ampla / contextual",
      "short_label": "Cena 1 – visão ampla",
      "description": "Prompt detalhado para o modelo de imagem gerar a primeira cena, incluindo: tipo de ambiente, suporte em que a AD_ARTWORK aparece (ex.: post do Instagram em um celular sobre a mesa), objetos ao redor, iluminação, clima, estilo fotorrealista e a instrução clara de usar a arte original do arquivo enviado sem alterar seu conteúdo."
    },
    {
      "id": "scene_2",
      "camera_angle": "eye_level",
      "shot_label": "Visão média / altura dos olhos",
      "short_label": "Cena 2 – visão média",
      "description": "Prompt detalhado para a segunda cena, com enquadramento em altura dos olhos, mostrando uso ou interação com a peça (ex.: alguém segurando o celular com o post aberto), ambiente, objetos, iluminação e a instrução de manter a AD_ARTWORK exatamente como enviada, apenas aplicada no suporte."
    },
    {
      "id": "scene_3",
      "camera_angle": "close_or_low_angle",
      "shot_label": "Close / ângulo dramático",
      "short_label": "Cena 3 – close ou dramático",
      "description": "Prompt detalhado para a terceira cena, com close-up ou ângulo dramático focado na peça (ex.: close na tela, close no cartão, outdoor visto de baixo), descrevendo ambiente, luz, textura, e reforçando que a AD_ARTWORK deve ser usada como está, sem qualquer alteração."
    }
  ]
}"}
